import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { mix, uv, vec3, vec4, smoothstep, fn, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh } = ctx.THREE;

  // Create primary container
  const mainGroup = new ThreeGroup();

  // Create cleanup list
  const activeTimelines = [];
  const activePrimitives = [];
  const resourcesToDispose = [];

  // Theme Colors
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const colInk = new Color(colors.ink);
  const colPaper = new Color(colors.paper);
  const colAccent = new Color(colors.accent);
  const colSurface = new Color(colors.surface);

  // --- STAGE / BACKDROP (As per W-PCP §9 No-flat-void constraint) ---
  const bgGeom = new PlaneGeometry(7.0, 6.0);
  resourcesToDispose.push(bgGeom);

  // Gradient Material Shader using NodeMaterials
  const bgMat = new MeshBasicNodeMaterial({ depthWrite: false });
  resourcesToDispose.push(bgMat);

  // Vertical gradient from ink (bottom) to surface (top)
  const uvCoords = uv();
  const gradientFactor = uvCoords.y;
  bgMat.colorNode = vec4(mix(vec3(colInk.r, colInk.g, colInk.b), vec3(colSurface.r, colSurface.g, colSurface.b), gradientFactor), 1.0);

  const backdropMesh = new ThreeMesh(bgGeom, bgMat);
  backdropMesh.position.set(0, 0, -2.5);
  mainGroup.add(backdropMesh);

  // --- COMPOSITION FRAME ---
  const frameGroup = new ThreeGroup();
  mainGroup.add(frameGroup);

  // Brushed Metal Plate (Card Plate Asset)
  const plateGeom = new PlaneGeometry(3.2, 1.8);
  resourcesToDispose.push(plateGeom);

  const plateMat = new MeshBasicNodeMaterial({ transparent: true });
  resourcesToDispose.push(plateMat);

  // Texture mapping for brushed metal
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      plateMat.colorNode = vec4(tex.sample(uvCoords).rgb, 0.85);
      plateMat.needsUpdate = true;
    });
  } else {
    // Elegant fallback fallback procedural surface
    plateMat.colorNode = vec4(mix(vec3(colSurface.r, colSurface.g, colSurface.b), vec3(colInk.r, colInk.g, colInk.b), uvCoords.x), 0.9);
  }

  const plateMesh = new ThreeMesh(plateGeom, plateMat);
  plateMesh.position.set(0, 0, -0.05);
  frameGroup.add(plateMesh);

  // Accenting subtle red engineering indicator border
  const accentGeom = new PlaneGeometry(3.24, 0.04);
  resourcesToDispose.push(accentGeom);
  const accentMat = new MeshBasicNodeMaterial({ color: colAccent });
  resourcesToDispose.push(accentMat);
  const accentStrip = new ThreeMesh(accentGeom, accentMat);
  accentStrip.position.set(0, -0.88, 0.01);
  frameGroup.add(accentStrip);

  // --- TEXT CONTENT (Rendered via fontAtlas MSDF as per W-PCP §9) ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(i => i.role === 'headline' || i.text.includes('Collection')) || { text: 'Collection 2' };

  // Create primary display text
  const textMesh = ctx.fontAtlas.createText(headlineItem.text.toUpperCase(), {
    fontSize: 0.18,
    color: colPaper,
    align: 'center'
  });
  textMesh.position.set(0, 0.1, 0.05);
  frameGroup.add(textMesh);

  // Mono visual descriptor / Subtitle
  const subTextMesh = ctx.fontAtlas.createText('ENGINEERED TO SPECIFICATION', {
    fontSize: 0.07,
    color: '#8e96a0',
    align: 'center',
    letterSpacingPx: 3
  });
  subTextMesh.position.set(0, -0.25, 0.05);
  frameGroup.add(subTextMesh);

  // --- CINEMATIC AMBIENCE & MOTION ---
  // Gentle entrance animation (Fade-up/rise-in with weighted-settle signature)
  frameGroup.position.y = -0.3;
  frameGroup.scale.set(0.95, 0.95, 0.95);

  const tl = gsap.timeline();
  tl.to(frameGroup.position, {
    y: 0,
    duration: 0.9,
    ease: 'power4.out'
  });
  tl.to(frameGroup.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  activeTimelines.push(tl);

  // Apply any primitives from layout config
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](frameGroup, prim.params);
        activePrimitives.push(result);
      }
    }
  }

  // --- CLEANUP ---
  mainGroup.userData = {
    handlers: {},
    cleanup: () => {
      activeTimelines.forEach(t => t.kill());
      activePrimitives.forEach(p => {
        if (typeof p.cleanup === 'function') p.cleanup();
      });
      resourcesToDispose.forEach(res => {
        if (res.dispose) res.dispose();
      });
    }
  };

  return mainGroup;
}
